    for FILE in \
      app/Services/Commerce/CommercePdpTechPackProjectionService.php \
      app/Services/Commerce/CommerceCatalogProjectionService.php \
      app/Services/Commerce/CommercePdpExperienceService.php \
      app/Services/Commerce/CommercePdpSizeAdvisorService.php \
      app/Console/Commands/Commerce/AuditPdpTechPackProjectionCommand.php
    do
        php -l "$FILE"
    done

    grep -Fq -- \
      "production_tech_pack_specs" \
      app/Services/Commerce/CommercePdpTechPackProjectionService.php

    grep -Fq -- \
      "'measurement_type' => 'garment'" \
      app/Services/Commerce/CommercePdpTechPackProjectionService.php

    grep -Fq -- \
      'CommercePdpTechPackProjectionService $techPackProjection' \
      app/Services/Commerce/CommerceCatalogProjectionService.php

    grep -Fq -- \
      'product_tech_pack_plus_generic_body_profile_v1' \
      app/Services/Commerce/CommercePdpExperienceService.php

    grep -Fq -- \
      "'fit_evidence' => \$fitEvidence" \
      app/Services/Commerce/CommercePdpSizeAdvisorService.php

    grep -Fq -- \
      'commerce:audit-pdp-tech-pack-projection' \
      app/Console/Commands/Commerce/AuditPdpTechPackProjectionCommand.php

    printf '%s\n' \
      'ERP_PDP_TECHPACK_STATIC_CONTRACT=PASS'

    trap - ERR

    artisan_safe optimize:clear

    printf '%s\n' \
      'LINXEN_PDP_TECHPACK_ERP_SOURCE_PATCH=PASS'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"
    printf '%s\n' \
      'TECHPACK_SELECTOR=SPEC_COUNT_THEN_ACTIVE_STATUS'
    printf '%s\n' \
      'MEASUREMENT_TYPE=GARMENT'
    printf '%s\n' \
      'BODY_MEASUREMENT_INFERENCE=BLOCKED'
    printf '%s\n' \
      'BOM_MATERIAL_PROJECTION=READ_ONLY'
    printf '%s\n' \
      'MIGRATION=NONE'
    printf '%s\n' \
      'DB_MUTATION=NONE'
    printf '%s\n' \
      'PROVIDER_CALL=NONE'
    printf '%s\n' \
      'ORDER_KIOTVIET_META_MUTATION=NONE'
    exit 0
fi

