SF_TECHPACK_V1_B64_5

    php -l app/Services/CommerceV2/CommerceV2Presenter.php
    php -l app/Console/Commands/CommerceV2PdpSalesExperienceSmokeCommand.php

    grep -Fq -- \
      "'structured' => (bool) data_get(" \
      app/Services/CommerceV2/CommerceV2Presenter.php

    grep -Fq -- \
      'data-lxpdp-size-chart-structured' \
      resources/views/commerce_v2/pages/product.blade.php

    grep -Fq -- \
      'Số đo thành phẩm' \
      resources/views/commerce_v2/pages/product.blade.php

    grep -Fq -- \
      'AI_PATCH_LINXEN_PDP_TECH_PACK_SIZE_CHART_V1' \
      public/commerce-v2/pdp-sales-experience.css

    grep -Fq -- \
      'lxpdp-advisor__evidence' \
      public/commerce-v2/pdp-sales-experience.js

    grep -Fq -- \
      'structured_tech_pack_chart' \
      app/Console/Commands/CommerceV2PdpSalesExperienceSmokeCommand.php

    if command -v node >/dev/null 2>&1; then
        set +e
        node --check public/commerce-v2/pdp-sales-experience.js
        NODE_STATUS=$?
        set -e

        if [ "$NODE_STATUS" -eq 0 ]; then
            printf '%s\n' 'PDP_JS_SYNTAX=PASS'
        else
            printf 'PDP_JS_SYNTAX=WARNING_EXIT_%s\n' \
              "$NODE_STATUS"
        fi
    else
        printf '%s\n' 'PDP_JS_SYNTAX=SKIPPED_NODE_MISSING'
    fi

    artisan_safe view:clear
    artisan_safe commerce-v2:pdp-sales-experience-smoke
    artisan_safe optimize:clear

    printf '%s\n' \
      'LINXEN_PDP_TECHPACK_STOREFRONT_SOURCE_PATCH=PASS'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"
    printf '%s\n' \
      'STRUCTURED_GARMENT_SIZE_CHART=ENABLED'
    printf '%s\n' \
      'TECHPACK_SOURCE_LABEL=ENABLED'
    printf '%s\n' \
      'SIZE_ADVISOR_FIT_EVIDENCE=ENABLED'
    printf '%s\n' \
      'CROSS_COLOR_MEDIA_FALLBACK=UNCHANGED_BLOCKED'
    printf '%s\n' \
      'EXACT_SELLABLE_SKU_CART_CONTRACT=PRESERVED'
    printf '%s\n' \
      'MIGRATION=NONE'
    printf '%s\n' \
      'DB_MUTATION=NONE'
    printf '%s\n' \
      'ERP_API_CALL_DURING_LOCAL_PATCH=NONE'
    printf '%s\n' \
      'ORDER_PROVIDER_META_MUTATION=NONE'
    printf '%s\n' \
      'NPM_BUILD=NOT_REQUIRED'
    printf '%s\n' \
      'V1_STOREFRONT=UNCHANGED'
    exit 0
fi

printf 'ERROR: Unsupported target: %s\n' "$TARGET" >&2
exit 1
